import OpenAI from "openai";
const derivative: Derivative = async ({ row, ref, db, storage, auth, logging }) => {
  try {
    const openaiApiKey = await rowy.secrets.get("openai");
    if (!openaiApiKey) {
      throw new Error('OpenAI API key not found');
    }
    const openai = new OpenAI({ apiKey: openaiApiKey });

    // Ensure each piece of data is valid; use fallback values if not
    const language = row.level?.language || 'English';
    const motherTongue = row.motherTongue || 'en';
    const levelCategory = row.level?.category || 'Beginner';
    const levelScore = (row.level?.score !== undefined && row.level.score !== null) ? `${row.level.score}/5` : '1/5';
    // Construct userText with validated or fallback data
    const userText = `Target language: ${language}. User's mother tongue: ${motherTongue}. User's level: ${levelCategory} ${levelScore}`;

    // Variables for model, focusOn, and userContent
    let model = `gpt-4-vision-preview`; // Default model
    let focusOn = `image`; // Default focus
    let userContent;

    // Check if image is uploaded
    if (!row.uploadImage || row.uploadImage.length === 0) {
      if (!row.requestTopic || row.requestTopic.length === 0) {
        return undefined;
      } else {
        // Update model, focusOn, and userContent for requestTopic
        model = `gpt-4-1106-preview`;
        focusOn = `topic`;
        userContent = `Topic: ${row.requestTopic}. \n\n ${userText}`; 
      }
    } else {
      userContent = [
                { type: "text", text: userText },
                { type: "image_url", image_url: row.uploadImage },
            ];
    }

    const systemprompt = `Create a story or meditation script that aligns with the theme of '${focusOn}'. The content should be captivating and relaxing, designed to facilitate language learning in an immersive and engaging way.
                          Guidelines:
                          Theme Selection: Choose a theme for the story or meditation. This could range from a tranquil nature scene for a meditation to an intriguing cultural tale for a story.
                          Language Level: Tailor the complexity of the language to the proficiency level of the target audience, whether beginners, intermediate, or advanced learners.
                          Vocabulary and Phrases: Integrate key vocabulary and phrases relevant to the theme, ensuring they are contextually appropriate and aid in language acquisition.
                          Narrative or Meditative Structure: For stories, focus on a clear, engaging narrative with a beginning, middle, and end. For meditations, structure the script to guide listeners through relaxation and visualization techniques.
                          Cultural Elements: If applicable, weave in cultural elements or nuances of the language being taught to enrich the learning experience.
                          Call to Action: Conclude with a gentle call to action or reflection, encouraging listeners to think about or practice what they've learned. 
                      Generate a set of data in the form of a JSON Array object with the following structure:
                      [
                        {
                          "text": "Dialogue into target language"
                        }
                      ]
                      ---
                      ONLY JSON ARRAY IS ALLOWED as an answer. No explanation or other text is allowed.`;
    // remove 2 items here
    //"session": "Session Name",
    //"theme": "Provide a short narrative to inspire an illustration that visually encapsulates the theme of the session."

    // API call to OpenAI
    const response = await openai.chat.completions.create({
      model: model,
      messages: [
        { role: "system", content: systemprompt },
        { role: "user", content: userContent },
      ],
      temperature: 1,
      max_tokens: 4095,
      top_p: 1,
      frequency_penalty: 0,
      presence_penalty: 0,
    });

    const responseData = response.choices[0].message?.content;
    if (!responseData) {
      throw new Error('No response data found');
    }
   // Regular expression to find only arry JSON object
    const regex = /(\[.*\])/s; // find a JSON object or array /(\{.*\}|\[.*\])/s
    // Extract JSON string using the regular expression.
    const jsonPart = responseData.match(regex);

    // Safe JSON parsing
    try {
      if (jsonPart) {
        const responseDataJson = JSON.parse(jsonPart);
        await ref.update({ storyJson: responseDataJson });
        return focusOn;
      } else {
        throw new Error('JSON part not found in the response data');
      }
    } catch (e) {
      logging.error('Error parsing JSON:', e.message);
      // Return the raw response data since JSON parsing failed
      return responseData;
    }

  } catch (error) {
    if (error instanceof OpenAI.APIError) {
      logging.log("OpenAI API Error:", error.name, "Status:", error.status);
    } else {
      logging.log("Error:", error.message);
    }

    return `false`;
  }
};
export default derivative;

