import fetch from 'node-fetch';

async function processBatch(batch, elevenlabsApiKey, row, ref, logging) {
  return Promise.all(batch.map(async (textInfo) => {
    if (textInfo.text) {
      const voice = row.elevenlabsVoiceId[0].voiceIdselected;

      const apiUrl = `https://api.elevenlabs.io/v1/text-to-speech/${voice}?optimize_streaming_latency=0`;
      const requestBody = {
        text: textInfo.text,
        model_id: "eleven_multilingual_v2",
        voice_settings: {
          stability: 0.5,
          similarity_boost: 0,
          style: 0,
          use_speaker_boost: true
        }
      };

      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Accept': 'audio/mpeg',
          'xi-api-key': elevenlabsApiKey,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const audioBuffer = await response.buffer();
        const file = await rowy.storage.upload.data(audioBuffer, {
          folderPath: ref.path + '/speech/'
        });
        textInfo.textAudio = file.downloadURL;
      } else {
        const errorMessage = `API call failed for text '${textInfo.text}': ${response.status} ${response.statusText}`;
        logging.error(errorMessage);
      }
    }
    return textInfo;
  }));
}

const derivative = async ({ row, ref, db, storage, auth, actionParams, user, logging }) => {
  try {
    const elevenlabsApiKey = await rowy.secrets.get('elevenlabs');
    if (!elevenlabsApiKey) {
      throw new Error('ElevenLabs API key not found');
    }

    if (!Array.isArray(row.storyJson) || row.storyJson.length === 0) {
      return undefined;
    }

    const batchSize = 3; // For the Starter plan
    let results = [];

    for (let i = 0; i < row.storyJson.length; i += batchSize) {
      const batch = row.storyJson.slice(i, i + batchSize);
      const batchResults = await processBatch(batch, elevenlabsApiKey, row, ref, logging);
      results = [...results, ...batchResults];
      await new Promise(resolve => setTimeout(resolve, 1000)); // 1-second delay between batches
    }

    row.storyJson = results;
    return row.storyJson;
  } catch (error) {
    logging.error('Error:', error.message);
    return { error: error.message };
  }

  return false;
};

