    //Get data of parent table
    const parentDoc: any = await ref.parent.parent.get().then(snap => snap.data());
    const storyLength = parentDoc.storyImage.length;
    logging.log(`Story length retrieved: ${storyLength}`);

    // Check if index is valid
    if (row.index === null || row.index === undefined || row.index < 0 || row.index >= storyLength || !row.speaker) {
