    };
    // Convert language name to code, default to 'en' if not found
    const languageCode = languageMap[parentDoc.level.language] || 'en';


    // Set the model version and input parameters
    const prediction = await replicate.predictions.create({
      version: "684bc3855b37866c0c65add2ff39c78f3dea3f4ff103a436465326e0f438d55e",
      input: {
